mapper.select:
select bp_id, member_no, record_date, bp_level, bp_high, bp_low
from blood_pressure 
where member_no=#{member_no}

mapper.update:
update blood_pressure set bp_id=#{bp_id}, member_no=#{member_no}, 
record_date=#{record_date}, bp_level=#{bp_level}, bp_high=#{bp_high}, 
bp_low=#{bp_low} where member_no=#{member_no}
